// ---- management presentation ------------------------------------------------
async dkInit() {
  try {
    const o = await Kav1.get("reports/deck/options");
    this.dkSlides = o.slides; this.dkViews = o.custom_views; this.dkStatusFilters = o.status_filters; this.dkTemplates = o.templates;
    const on = {}; o.slides.forEach(s => { on[s.key] = s.default; }); this.dk.on = on;
    this.dkPreset();
  } catch (e) { /* the card stays empty when the feature is missing */ }
},
dkPreset() {
  const n = new Date(), y = n.getFullYear(), m = n.getMonth(), f = d => this.crFmt(d);
  const q = Math.floor(m / 3) * 3; let a = null, b = null;
  switch (this.dk.preset) {
    case "month": a = new Date(y, m, 1); b = new Date(y, m + 1, 0); break;
    case "last_month": a = new Date(y, m - 1, 1); b = new Date(y, m, 0); break;
    case "quarter": a = new Date(y, q, 1); b = new Date(y, q + 3, 0); break;
    case "last_quarter": a = new Date(y, q - 3, 1); b = new Date(y, q, 0); break;
    case "year": a = new Date(y, 0, 1); b = n; break;
    case "last90": b = n; a = new Date(n.getTime() - 89 * 864e5); break;
    default: return;
  }
  if (b > n) b = n;
  this.dk.from = f(a); this.dk.to = f(b);
},
dkParams() {
  const from = this.crIso(this.dk.from), to = this.crIso(this.dk.to);
  if (!from || !to) { this.dkErr = true; this.dkMsg = "כתוב תאריך התחלה ותאריך סיום בפורמט יום.חודש.שנה, למשל 31.12.2026"; return null; }
  if (from > to) { this.dkErr = true; this.dkMsg = "'מתאריך' מאוחר מ'עד תאריך'"; return null; }
  const slides = this.dkSlides.filter(s => this.dk.on[s.key]).map(s => s.key);
  if (!slides.length && !this.dk.custom.length) { this.dkErr = true; this.dkMsg = "בחר לפחות שקף אחד"; return null; }
  this.dkMsg = "";
  return { date_from: from, date_to: to, title: this.dk.title, project: this.dk.project, inviter: this.dk.inviter, slides, custom: this.dk.custom.map(c => ({ ...c })),
           show_names: !!this.dk.names, template_id: this.dk.template ? +this.dk.template : null };
},
async dkDownload() {
  const p = this.dkParams(); if (!p) return;
  this.dkBusy = true;
  try {
    const res = await fetch("/reports/deck/export", { method: "POST", credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: JSON.stringify(p) });
    if (!res.ok) throw new Error(await Kav1.errorText(res, "שגיאה ביצירת המצגת"));
    const blob = await res.blob(), d = new Date(), pad = n => String(n).padStart(2, "0");
    Kav1.download(blob, "kav1_management_deck_" + d.getFullYear() + pad(d.getMonth() + 1) + pad(d.getDate()) + ".pptx");
    this.dkErr = false; this.dkMsg = "המצגת נוצרה";
  } catch (e) { this.dkErr = true; this.dkMsg = e.message; }
  this.dkBusy = false;
},
async dkUploadTemplate() {
  if (!this.dkFile) return;
  this.dkBusy = true;
  try {
    const name = (this.dk.tplName || this.dkFile.name.replace(/\.pptx$/i, "")).trim();
    const res = await fetch("/reports/deck/templates?name=" + encodeURIComponent(name), { method: "POST", body: this.dkFile, credentials: "same-origin" });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(data.detail || "התבנית לא נשמרה");
    this.dkTemplates = await Kav1.get("reports/deck/templates"); this.dk.template = String(data.id); this.dkFile = null; this.dk.tplName = "";
    this.dkErr = false; this.dkMsg = "התבנית נשמרה ונבחרה";
  } catch (e) { this.dkErr = true; this.dkMsg = e.message; }
  this.dkBusy = false;
},
async dkDeleteTemplate() {
  if (!this.dk.template || !confirm("למחוק את התבנית?")) return;
  try { await Kav1.del("reports/deck/templates/" + this.dk.template); this.dkTemplates = await Kav1.get("reports/deck/templates"); this.dk.template = ""; this.dkErr = false; this.dkMsg = "התבנית נמחקה"; }
  catch (e) { this.dkErr = true; this.dkMsg = e.message; }
},
async dkShow() {
  const p = this.dkParams(); if (!p) return;
  this.dkBusy = true;
  try { this.dkDeck = await Kav1.post("reports/deck/data", p); this.dkIdx = 0; this.dkOpen = true; this.$nextTick(() => { this.dkRender(); const el = document.querySelector(".dk-overlay"); if (el) el.focus(); }); }
  catch (e) { this.dkErr = true; this.dkMsg = e.message; }
  this.dkBusy = false;
},
dkClose() { this.dkOpen = false; if (this.dkChart) { try { this.dkChart.destroy(); } catch (e) {} this.dkChart = null; } try { if (document.fullscreenElement) document.exitFullscreen(); } catch (e) {} },
dkFull() { try { const el = document.querySelector(".dk-overlay"); if (el && el.requestFullscreen) el.requestFullscreen(); } catch (e) {} },
dkGo(step) { const n = Math.max(0, Math.min(this.dkDeck.slides.length, this.dkIdx + step)); if (n !== this.dkIdx) { this.dkIdx = n; this.dkRender(); } },
dkKey(ev) {
  if (!this.dkOpen) return;
  if (["ArrowLeft", "PageDown", " ", "Enter"].includes(ev.key)) { ev.preventDefault(); this.dkGo(1); }
  else if (["ArrowRight", "PageUp", "Backspace"].includes(ev.key)) { ev.preventDefault(); this.dkGo(-1); }
  else if (ev.key === "Home") { this.dkIdx = 0; this.dkRender(); }
  else if (ev.key === "End") { this.dkIdx = this.dkDeck.slides.length; this.dkRender(); }
  else if (ev.key === "Escape") { this.dkClose(); }
},
dkRender() {
  const st = document.getElementById("dkStage"); if (!st) return;
  if (this.dkChart) { try { this.dkChart.destroy(); } catch (e) {} this.dkChart = null; }
  const esc = t => String(t == null ? "" : t).replace(/[&<>"]/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
  const d = this.dkDeck;
  if (this.dkIdx === 0) { st.innerHTML = '<div class="dk-cover"><h1>' + esc(d.title) + '</h1><p>' + esc(d.subtitle) + '</p><p style="margin-top:10px;font-size:14px;">הופק: ' + esc(d.generated) + '</p></div>'; return; }
  const s = d.slides[this.dkIdx - 1];
  let html = '<h2 class="dk-title">' + esc(s.title) + '</h2>';
  if (s.kpis) html += '<div class="dk-kpis">' + s.kpis.map(k => '<div class="dk-kpi"><b>' + esc(k.value) + '</b><span>' + esc(k.label) + '</span></div>').join("") + '</div>';
  const hasTable = s.table && s.table.rows && s.table.rows.length;
  if (s.chart || hasTable) {
    html += '<div class="dk-body' + (s.chart && hasTable ? "" : " one") + '">';
    if (s.chart) html += '<div class="dk-chart"><canvas id="dkCanvas"></canvas></div>';
    if (hasTable) html += '<div style="overflow:auto;"><table class="data"><thead><tr>' + s.table.columns.map(c => '<th>' + esc(c) + '</th>').join("") + '</tr></thead><tbody>' +
      s.table.rows.map(r => '<tr>' + r.map(v => '<td>' + esc(v) + '</td>').join("") + '</tr>').join("") + '</tbody></table>' + (s.table.note ? '<p class="muted" style="font-size:12px;">' + esc(s.table.note) + '</p>' : "") + '</div>';
    html += '</div>';
  }
  if (s.note) html += '<p class="muted" style="margin-top:14px;">' + esc(s.note) + '</p>';
  st.innerHTML = html;
  if (s.chart && typeof Chart !== "undefined") this.dkDraw(s.chart);
},
dkDraw(ch) {
  const el = document.getElementById("dkCanvas"); if (!el) return;
  const colors = ["#3a7bd5", "#f2a93b", "#4caf7d", "#d35a5a", "#7b8fb5", "#9b6dd8"], text = "#e0e0e0", grid = "rgba(255,255,255,0.08)";
  const pie = ch.type === "doughnut" || ch.type === "pie";
  const datasets = ch.series.map((s, i) => pie
    ? { label: s.name, data: s.values, backgroundColor: ch.categories.map((_, j) => colors[j % colors.length]), borderColor: "#2d2d2d", borderWidth: 2 }
    : ch.type === "line" ? { label: s.name, data: s.values, borderColor: colors[i % 6], backgroundColor: colors[i % 6] + "33", tension: 0.25, fill: true, pointRadius: 3 }
    : { label: s.name, data: s.values, backgroundColor: colors[i % 6] });
  const stacked = ch.type === "stackedbar";
  const opts = { responsive: true, maintainAspectRatio: false, animation: false, plugins: { legend: { display: pie || ch.series.length > 1, position: "bottom", labels: { color: text } } } };
  if (!pie) opts.scales = { x: { stacked, ticks: { color: text }, grid: { color: grid } }, y: { stacked, beginAtZero: true, ticks: { color: text, precision: 0 }, grid: { color: grid } } };
  this.dkChart = new Chart(el, { type: pie ? ch.type : (ch.type === "line" ? "line" : "bar"), data: { labels: ch.categories, datasets }, options: opts });
},
// ---- custom reports -------------------------------------------------------
async crInit() {
  try {
    const o = await Kav1.get("reports/custom/options");
    this.crTypes = o.types; this.crFields = o.expiry_fields; this.crProjects = o.projects; this.crInviters = o.inviters || []; this.crInfosec = o.infosec_filters || this.crInfosec; this.crSorts = o.sorts || this.crSorts; this.cr.warn = o.warn_days;
  } catch (e) { /* the card just stays empty */ }
},
crReset() { this.crResult = null; this.crMsg = ""; this.cr.sort = this.cr.type === "infosec" ? "project" : "expiry"; },
// day.month.year typed by hand (also 1/2/26) -> 2026-02-01; "" -> ""; invalid -> null
crIso(text) {
  const t = (text || "").trim();
  if (!t) return "";
  const m = t.match(/^(\d{1,2})[./\-](\d{1,2})[./\-](\d{2}|\d{4})$/);
  if (!m) return null;
  let y = +m[3]; if (m[3].length === 2) y += 2000;
  const d = new Date(y, +m[2] - 1, +m[1]);
  if (d.getFullYear() !== y || d.getMonth() !== +m[2] - 1 || d.getDate() !== +m[1]) return null;
  return y + "-" + String(+m[2]).padStart(2, "0") + "-" + String(+m[1]).padStart(2, "0");
},
crFmt(d) { const p = n => String(n).padStart(2, "0"); return p(d.getDate()) + "." + p(d.getMonth() + 1) + "." + d.getFullYear(); },
crQuick(days) { const to = new Date(), from = new Date(); from.setDate(from.getDate() - days); this.cr.from = this.crFmt(from); this.cr.to = this.crFmt(to); },
crMonth() { const n = new Date(); this.cr.from = this.crFmt(new Date(n.getFullYear(), n.getMonth(), 1)); this.cr.to = this.crFmt(new Date(n.getFullYear(), n.getMonth() + 1, 0)); },
crQuery() {
  const from = this.crIso(this.cr.from), to = this.crIso(this.cr.to);
  if (from === null) { this.crMsg = "'מתאריך' לא תקין. כתוב יום.חודש.שנה, למשל 31.12.2026"; return null; }
  if (to === null) { this.crMsg = "'עד תאריך' לא תקין. כתוב יום.חודש.שנה, למשל 31.12.2026"; return null; }
  if (from && to && from > to) { this.crMsg = "'מתאריך' מאוחר מ'עד תאריך'"; return null; }
  this.crMsg = "";
  const q = new URLSearchParams({ type: this.cr.type });
  if (this.cr.type !== "visitors" && this.cr.type !== "infosec_summary") { if (from) q.set("date_from", from); if (to) q.set("date_to", to); }
  if (this.cr.type === "infosec" || this.cr.type === "expiry") { q.set("infosec", this.cr.infosec); q.set("sort", this.cr.sort); }
  if (this.cr.project) q.set("project", this.cr.project);
  if (this.cr.inviter && (this.cr.type === "invitees" || this.cr.type === "inviter_summary")) q.set("inviter", this.cr.inviter);
  if (this.cr.type === "activity") q.set("action", this.cr.action);
  if (this.cr.type === "expiry") {
    q.set("field", this.cr.field); q.set("status", this.cr.status);
    if (this.cr.status === "expiring" && this.cr.warn !== "" && this.cr.warn != null) q.set("warn_days", this.cr.warn);
  }
  return q.toString();
},
async crRun() {
  const q = this.crQuery(); if (q === null) return;
  try { this.crResult = await Kav1.get("reports/custom?" + q); }
  catch (e) { this.crResult = null; this.crMsg = e.message; }
},
async crExport() {
  const q = this.crQuery(); if (q === null) return;
  try {
    const res = await fetch("/reports/custom/export?" + q, { credentials: "same-origin" });
    if (!res.ok) throw new Error(await Kav1.errorText(res, "שגיאה בייצוא"));
